                                                                                                                                                                                                            
  CREATE TABLE "FMP_SCOPE"                                                                                                                                                                        
   (	"SCOPE_ID" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"REFERENCE_ID" NUMBER(20,0),                                                                                                                                                                               
	"REFERENCE_TYPE" VARCHAR2(64),                                                                                                                                                                             
	"ENTITY_TYPE" VARCHAR2(64) DEFAULT 'USER' NOT NULL ENABLE,                                                                                                                                                 
	"USER_ID" VARCHAR2(256),                                                                                                                                                                                   
	"SOURCE_USER_ID" VARCHAR2(256),                                                                                                                                                                            
	"PERMISSIONS_TYPE" NVARCHAR2(64),                                                                                                                                                                          
	"ROLE_ID" NUMBER(20,0),                                                                                                                                                                                    
	"CREATED_BY" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                                 
	"CREATION_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                      
	"UPDATED_BY" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                                 
	"UPDATE_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                        
	"RANGE_TYPE" VARCHAR2(64),                                                                                                                                                                                 
	"RANGE_ID" VARCHAR2(256),                                                                                                                                                                                  
	"IS_INHERIT_PERMISSION" NUMBER(20,0) DEFAULT 1,                                                                                                                                                            
	 PRIMARY KEY ("SCOPE_ID")                                                                                                                                                                                  
  USING INDEX  ENABLE                                                                                                                                                                                       
   ) ;                                                                                                                                                                                                      


